Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <cstdio>
#include <vector>
#include <cmath>
#include <ctime>
#include <functional>

using namespace std;

void solve();

int main() {
#ifdef LOCAL
    freopen("input.txt", "r", stdin);
    auto start = clock();
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.precision(10);
    cout << fixed;
    int t = 1;
    while (t--) solve();
#ifdef LOCAL
    cerr << endl << endl << (clock() - start) / double(CLOCKS_PER_SEC) << endl;
#endif
    return 0;
}

void solve() {
    int n, k;
    cin >> n >> k;
    vector<double> allp(n);
    for (int i = 0; i < n; ++i) cin >> allp[i];

    for (int banned = 0; banned < n; ++banned) {
        double base = allp[banned];
        if (fabs(base) < 1e-6) {
            cout << "0 ";
            continue;
        }

        int m = n - 1;
        vector<double> p;
        p.reserve(m);
        for (int i = 0; i < n; ++i)
            if (i != banned) p.push_back(allp[i]);

        int total = 1 << m;
        vector<double> memo(total, 0.0);
        vector<char> ready(total, 0);

        function<double(int)> dp;
        dp = [&](int mask) -> double {
            if (ready[mask]) return memo[mask];
            double res;
            if (mask == 0) {
                res = base;
            } else {
                double sumP = 0.0;
                double sum = 0.0;
                for (int bit = 0; bit < m; ++bit) {
                    if (mask & (1 << bit)) {
                        sumP += p[bit];
                        sum += p[bit] * dp(mask ^ (1 << bit));
                    }
                }
                res = sum / (1.0 - sumP);
            }
            memo[mask] = res;
            ready[mask] = 1;
            return res;
        };

        double ans = dp(0);
        for (int mask = 1; mask < total; ++mask) {
            if (__builtin_popcount((unsigned)mask) < k)
                ans += dp(mask);
        }
        cout << ans << ' ';
    }
}
